# Required libraries
library(maftools)
library(TCGAmutations)  # for TCGA MAF loading
library(survival)

# -----------------------------------------------------------------------------
# 1. Load TCGA-BRCA MAF (RDS previously generated by maftools-mcp)
# -----------------------------------------------------------------------------
maf_rds_path <- "/Users/linqingxuan/mcp_server/maftools_mcp/src/maftools_mcp/tcga_data/BRCA.rds"
maf <- readRDS(maf_rds_path)

# -----------------------------------------------------------------------------
# 2. Prepare clinical data with OS time / status
#    (TCGA MAF objects from TCGAmutations include CDR clinical fields)
# -----------------------------------------------------------------------------
clin <- getClinicalData(maf)

# Ensure OS columns are numeric
clin$CDR_OS      <- as.numeric(as.character(clin$CDR_OS))
clin$CDR_OS.time <- as.numeric(as.character(clin$CDR_OS.time))

# Re-attach cleaned clinical data
maf@clinical.data <- clin

# -----------------------------------------------------------------------------
# 3. Survival analysis grouped by TP53 mutation status
#    - Group 1 (Geneset): samples with a TP53 mutation
#    - Group 2 (WT)     : samples without any TP53 mutation
# -----------------------------------------------------------------------------
output_dir <- "/Users/linqingxuan/maftools-mcp/Use-case_evaluation&repeated-run_performance/prompt_robustness/claude-opus-4.7/case_03/run_02/outputs"
dir.create(output_dir, showWarnings = FALSE, recursive = TRUE)

png(
  filename = file.path(output_dir, "mafSurvGroup.png"),
  width    = 2000,
  height   = 2000,
  res      = 300
)

mafSurvGroup(
  maf     = maf,
  geneSet = c("TP53"),
  time    = "CDR_OS.time",
  Status  = "CDR_OS"
)

dev.off()

